//! Consume one completed original Trainer client into sealed local readback.
//! The original channel, request counter and absolute lifetime stay in place.

use std::sync::Arc;

use super::Error;
use super::OriginalCellQ24TrainingCommandClientV1;
use super::OriginalCellQ24TrainingCommandReceiptV1;
use super::now;
use super::wire;

impl OriginalCellQ24TrainingCommandClientV1 {
    pub(crate) fn seal_original_completed_readback(
        self,
        expected: &OriginalCellQ24TrainingCommandReceiptV1,
    ) -> Result<Arc<Self>, Error> {
        let retained = self.retained.try_lock().map_err(|_| Error::Unavailable)?;
        let original = retained.as_ref().ok_or(Error::ReadbackRequired)?;
        if original != expected {
            return Err(Error::Binding("same completed original Trainer before sharing"));
        }
        let mut slot = self.channel.try_lock().map_err(|_| Error::Unavailable)?;
        let channel = slot.as_mut().ok_or(Error::Unavailable)?;
        channel.peer.check_peer_lifetime()?;
        let authenticated = wire::authenticate_receipt(
            &self.context,
            original.receipt().clone(),
            original.attestation().clone(),
            now()?,
        )?;
        if &authenticated != original {
            return Err(Error::Binding("full original Trainer signature before sharing"));
        }
        // This is a one-way attenuation of the same client, not a new channel.
        channel.execution_requested = true;
        drop(slot);
        drop(retained);
        Ok(Arc::new(self))
    }
}

//! The actual original Observer owner retains each fixed command profile and
//! its original T/B/S clients. No cached receipt substitutes for those reads.

use super::*;
use crate::OriginalCellEvaluationCommandClientV1;
use crate::OriginalCellQ24TrainingCommandClientV1;
use crate::OriginalCircuitEvaluatedNextUseRemoteSourcesV1;
use codex_hepta_learning_artifacts::LearningIterationReceiptV1;
use codex_hepta_learning_ledger::SignedLearningEvidenceV1;

pub(super) enum OriginalPredecessors {
    Legacy(LearningIterationEvidenceClientV1),
    SharedEvaluated(crate::OriginalCircuitPublishedEvidenceReadbackV1),
    Evaluated {
        trainer: OriginalCellQ24TrainingCommandClientV1,
        evaluator: OriginalCellEvaluationCommandClientV1,
    },
}

impl<W: AnchorWitnessStore + Send + 'static> OriginalCircuitNextUseCommandOwnerV1<W> {
    pub(crate) fn from_original_evaluated_receipt_owner(
        owner: OriginalCircuitNextUseReceiptOwnerV1<W>,
        live: OriginalCircuitLearningReadClientV1,
        trainer: OriginalCellQ24TrainingCommandClientV1,
        evaluator: OriginalCellEvaluationCommandClientV1,
        selector: LearningIterationEvidenceClientV1,
    ) -> Result<Self, Error> {
        let original = owner
            .original_evaluated_command_selection()
            .ok_or(Error::Binding("original evaluated Observer custody"))?;
        let context = OriginalCircuitNextUseCommandContextV1::from_evaluated_selection(original)?;
        live.require_original_evaluated_next_use(original)
            .map_err(OriginalCircuitNextUseReceiptErrorV1::from)?;
        let (_, readback_only) = owner.original_command_profile();
        let initial = context.initial()?;
        if selector.initial != initial
            || selector.actor_id != context.selection.owners.selector
            || selector.verifier.trust_digest() != context.verifier.trust_digest()
            || selector.verifier.scope_digest() != context.verifier.scope_digest()
            || selector.verifier.objective_digest() != context.verifier.objective_digest()
        {
            return Err(Error::Binding(
                "same original evaluated Selector readback client",
            ));
        }
        let binding = context.binding(now()?)?;
        Ok(Self {
            owner: Mutex::new(owner),
            live,
            predecessors: OriginalPredecessors::Evaluated { trainer, evaluator },
            selector,
            context,
            initial_head: initial.head_digest,
            binding,
            execution_requested: AtomicBool::new(readback_only),
            runtime: Handle::try_current().map_err(|_| Error::Unavailable)?,
            connections: Arc::new(Semaphore::new(4)),
        })
    }

    pub(crate) fn from_original_evaluated_shared_receipt_owner(
        owner: OriginalCircuitNextUseReceiptOwnerV1<W>,
        live: OriginalCircuitLearningReadClientV1,
        shared: crate::OriginalCircuitPublishedEvidenceReadbackV1,
        selector: LearningIterationEvidenceClientV1,
    ) -> Result<Self, Error> {
        let original = owner
            .original_evaluated_command_selection()
            .ok_or(Error::Binding("original evaluated Observer custody"))?;
        shared.require_original_context(original.original_context())
            .map_err(OriginalCircuitNextUseReceiptErrorV1::from)?;
        let context = OriginalCircuitNextUseCommandContextV1::from_evaluated_selection(original)?;
        live.require_original_evaluated_next_use(original)
            .map_err(OriginalCircuitNextUseReceiptErrorV1::from)?;
        let (_, readback_only) = owner.original_command_profile();
        let initial = context.initial()?;
        if selector.initial != initial
            || selector.actor_id != context.selection.owners.selector
            || selector.verifier.trust_digest() != context.verifier.trust_digest()
            || selector.verifier.scope_digest() != context.verifier.scope_digest()
            || selector.verifier.objective_digest() != context.verifier.objective_digest()
        {
            return Err(Error::Binding(
                "same original evaluated Selector readback client",
            ));
        }
        let binding = context.binding(now()?)?;
        Ok(Self {
            owner: Mutex::new(owner),
            live,
            predecessors: OriginalPredecessors::SharedEvaluated(shared),
            selector,
            context,
            initial_head: initial.head_digest,
            binding,
            execution_requested: AtomicBool::new(readback_only),
            runtime: Handle::try_current().map_err(|_| Error::Unavailable)?,
            connections: Arc::new(Semaphore::new(4)),
        })
    }

    pub(super) fn observe_original(
        &self,
        owner: &mut OriginalCircuitNextUseReceiptOwnerV1<W>,
        action: wire::Action,
    ) -> Result<
        (LearningIterationReceiptV1, SignedLearningEvidenceV1),
        OriginalCircuitNextUseReceiptErrorV1,
    > {
        match &self.predecessors {
            OriginalPredecessors::Legacy(trainer) => {
                let source = OriginalCircuitNextUseRemoteSourcesV1 {
                    snapshot: &self.context.selection,
                    live: &self.live,
                    trainer,
                    selector: &self.selector,
                };
                match action {
                    wire::Action::Execute => self.runtime.block_on(
                        OriginalCircuitNextUseReceiptOwnerV1::attest_original_remote_completion(
                            owner, source,
                        ),
                    ),
                    wire::Action::Readback => self.runtime.block_on(
                        OriginalCircuitNextUseReceiptOwnerV1::readback_remote(owner, source),
                    ),
                }
            }
            OriginalPredecessors::SharedEvaluated(shared) => {
                let selection = self.context.evaluated.as_ref().ok_or(
                    crate::learning_owner_journal::LearningOriginalOwnerErrorV1::Binding(
                        "original evaluated Observer command profile",
                    ),
                )?;
                shared.require_original_context(selection.original_context())?;
                let (trainer, evaluator) = shared.original_clients();
                let source = OriginalCircuitEvaluatedNextUseRemoteSourcesV1 {
                    snapshot: &self.context.selection,
                    selection,
                    live: &self.live,
                    trainer,
                    evaluator,
                    selector: &self.selector,
                };
                let original = match action {
                    wire::Action::Execute => self.runtime.block_on(
                        OriginalCircuitNextUseReceiptOwnerV1::attest_original_evaluated_remote_completion(owner, source)),
                    wire::Action::Readback => self.runtime.block_on(
                        OriginalCircuitNextUseReceiptOwnerV1::readback_evaluated_remote_completion(owner, source)),
                }?;
                Ok((original.receipt().clone(), original.attestation().clone()))
            }
            OriginalPredecessors::Evaluated { trainer, evaluator } => {
                let selection = self.context.evaluated.as_ref().ok_or(
                    crate::learning_owner_journal::LearningOriginalOwnerErrorV1::Binding(
                        "original evaluated Observer command profile",
                    ),
                )?;
                let source = OriginalCircuitEvaluatedNextUseRemoteSourcesV1 {
                    snapshot: &self.context.selection,
                    selection,
                    live: &self.live,
                    trainer,
                    evaluator,
                    selector: &self.selector,
                };
                let original = match action {
                    wire::Action::Execute => self.runtime.block_on(
                        OriginalCircuitNextUseReceiptOwnerV1::attest_original_evaluated_remote_completion(owner, source)),
                    wire::Action::Readback => self.runtime.block_on(
                        OriginalCircuitNextUseReceiptOwnerV1::readback_evaluated_remote_completion(owner, source)),
                }?;
                Ok((original.receipt().clone(), original.attestation().clone()))
            }
        }
    }
}

//! Original evaluated C attestation over the same remote published-task owner.
//! Read-only T/B/S capabilities do not grant task execution or a new signature.

use super::*;

pub struct OriginalCircuitEvaluatedNextUseRemoteSourcesV1<'a> {
    pub snapshot: &'a LearningIterationSnapshotV1,
    pub selection: &'a OriginalCircuitEvaluatedSelectionReceiptV1,
    pub live: &'a OriginalCircuitLearningReadClientV1,
    pub trainer: &'a OriginalCellQ24TrainingCommandClientV1,
    pub evaluator: &'a OriginalCellEvaluationCommandClientV1,
    pub selector: &'a LearningIterationEvidenceClientV1,
}

impl NextUseSources for OriginalCircuitEvaluatedNextUseRemoteSourcesV1<'_> {
    fn snapshot(&self) -> &LearningIterationSnapshotV1 {
        self.snapshot
    }
    fn trainer(&self) -> Option<&LearningIterationEvidenceClientV1> {
        None
    }
    fn selector(&self) -> &LearningIterationEvidenceClientV1 {
        self.selector
    }
    fn evaluated_owners(
        &self,
    ) -> Option<(
        &OriginalCellQ24TrainingCommandClientV1,
        &OriginalCellEvaluationCommandClientV1,
    )> {
        Some((self.trainer, self.evaluator))
    }
    fn location(&self) -> ObservationLocation {
        // Match the original evaluated owner ordering: final live Source/Cell
        // read follows every awaited T/B/S predecessor read.
        ObservationLocation::EvaluatedOwner
    }

    fn require_profile(&self, profile: &Profile) -> Result<(), Error> {
        let Profile::Evaluated(original) = profile else {
            return Err(OwnerError::Binding("original evaluated remote NextUse profile").into());
        };
        if self.selection.snapshot() != original.snapshot()
            || self.selection.original_receipt_binding() != original.original_receipt_binding()
        {
            return Err(OwnerError::Binding("same original evaluated remote Selection").into());
        }
        self.live.require_original_evaluated_next_use(original)?;
        Ok(())
    }

    async fn observe(
        &self,
        _config: &OriginalCircuitNextUseReceiptConfigV1,
    ) -> Result<LearningIterationObservationV1, Error> {
        let original = OriginalCircuitLearningReadClientV1::read_current(self.live).await?;
        Ok(original.observation().clone())
    }
}

impl<W: AnchorWitnessStore> OriginalCircuitNextUseReceiptOwnerV1<W> {
    pub(crate) fn original_evaluated_command_selection(
