fn now() -> Result<u64, Error> {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|at| at.as_secs())
        .map_err(|_| Error::Clock)
}
fn require_clock(started: u64, fresh: u64) -> Result<(), Error> {
    if fresh < started {
        return Err(Error::Clock);
    }
    Ok(())
}

