        evaluator: OriginalCellEvaluationCommandConnectionV1,
        inputs: RetainedVersionInputsV1,
        task: OriginalCircuitRetainedTaskInputsV1,
        artifact_checkpoint: OriginalCircuitRetainedArtifactCheckpointV1,
        final_use_issuer: AgentdUnixFinalUseGrantProvider,
        lifetime: Duration,
    ) -> Result<Self, Error> {
        Self::from_original_profile(
            material,
            dataset,
            trainer,
            InitialVersionEvidence::EvaluatedNoUpdate(evaluator),
            inputs,
            task,
            artifact_checkpoint,
            final_use_issuer,
            lifetime,
        )
    }

    fn from_original_profile(
        material: OriginalCellQ24MaterialReceiptConfigV1,
        dataset: OriginalCellQ24DatasetCommandReadbackV1,
        trainer: OriginalCellQ24TrainingCommandConnectionV1,
        evidence: InitialVersionEvidence,
        inputs: RetainedVersionInputsV1,
        task: OriginalCircuitRetainedTaskInputsV1,
        artifact_checkpoint: OriginalCircuitRetainedArtifactCheckpointV1,
        final_use_issuer: AgentdUnixFinalUseGrantProvider,
        lifetime: Duration,
    ) -> Result<Self, Error> {
        let purpose = evidence.purpose();
        let started = super::now()?;
        let (initial_binding, at) =
            OriginalCellQ24MaterialReceiptConfigV1::require_original_command_initial(&material)?;
        super::require_clock(started, at)?;
        OriginalCellQ24DatasetCommandReadbackV1::require_initial_context(&dataset, &material)?;
        task.require_completed_a(&inputs.completed)?;
        let artifacts = RetainedVersionArtifactOwnerV1::new(
            Arc::clone(&inputs.authorities.artifacts),
            artifact_checkpoint,
            inputs.selection.signed.clone(),
            inputs.selection.verifier.clone(),
        )?;
        let control = Arc::clone(&inputs.current);
        let final_use_issuer =
            AgentdUnixFinalUseGrantProvider::into_original_retained_version_issuer(
                final_use_issuer,
            )?;
        let phase = RetainedVersionHostPhaseV1::Awaiting {
            inputs: Box::new(inputs),
            task,
        };
        Self::new(
            material,
            initial_binding,
            RetainedVersionOriginV1::Fresh,
            purpose,
            RetainedVersionHostStateV1 {
                dataset,
                initial_trainer: Some(trainer),
                trainer: None,
                initial_evaluator: evidence.into_evaluator(),
                evaluator: None,
                shared_evaluated: None,
                cut: None,
                expected: None,
                control,
                artifacts,
                phase: Some(phase),
                selection_reader: None,
                final_use_issuer: Some(final_use_issuer),
            },
            lifetime,
        )
    }

    /// Cold expected bytes are accepted only by this permanent read-only
    /// constructor, then compared with actual D/T before any response.
    pub fn recover_from_original_owners(
        material: OriginalCellQ24MaterialReceiptConfigV1,
        dataset: OriginalCellQ24DatasetCommandReadbackV1,
        trainer: OriginalCellQ24TrainingCommandConnectionV1,
        original: OriginalCircuitRetainedVersionRecoveryV1,
        lifetime: Duration,
    ) -> Result<Self, Error> {
        Self::recover_original_profile(
            material,
            dataset,
            trainer,
            InitialVersionEvidence::TrainingNoUpdate,
            original,
            lifetime,
        )
    }

    /// Read-only cold recovery of a complete four-cut evaluated NoUpdate.
    /// The original E connection and already-held C owners remain mandatory.
    pub fn recover_from_original_evaluated_owners(
        material: OriginalCellQ24MaterialReceiptConfigV1,
        dataset: OriginalCellQ24DatasetCommandReadbackV1,
        trainer: OriginalCellQ24TrainingCommandConnectionV1,
        evaluator: OriginalCellEvaluationCommandConnectionV1,
        original: OriginalCircuitRetainedVersionRecoveryV1,
        lifetime: Duration,
    ) -> Result<Self, Error> {
        Self::recover_original_profile(
            material,
            dataset,
            trainer,
            InitialVersionEvidence::EvaluatedNoUpdate(evaluator),
            original,
            lifetime,
        )
    }

    fn recover_original_profile(
        material: OriginalCellQ24MaterialReceiptConfigV1,
        dataset: OriginalCellQ24DatasetCommandReadbackV1,
        trainer: OriginalCellQ24TrainingCommandConnectionV1,
        evidence: InitialVersionEvidence,
        original: OriginalCircuitRetainedVersionRecoveryV1,
        lifetime: Duration,
    ) -> Result<Self, Error> {
        let purpose = evidence.purpose();
        let count = match purpose {
            RetainedVersionPurposeV1::TrainingNoUpdate => 3,
            RetainedVersionPurposeV1::EvaluatedNoUpdate => 4,
        };
        let (initial_binding, _) =
            OriginalCellQ24MaterialReceiptConfigV1::require_original_command_initial(&material)?;
        OriginalCellQ24DatasetCommandReadbackV1::require_initial_context(&dataset, &material)?;
        if original.intent_digest.is_zero()
            || original.training.receipts.len() != count
            || original.attestations.len() != count
        {
            return Err(Error::Binding("original retained recovery cut"));
        }
        let artifacts = RetainedVersionArtifactOwnerV1::new(
            original.artifacts,
            original.artifact_checkpoint,
            original.artifact_selection,
            original.artifact_verifier,
        )?;
        let phase = RetainedVersionHostPhaseV1::Recovered(RetainedVersionInstalledTaskV1 {
            cell: original.cell,
            source: original.source,
            identity: original.identity,
            intent: original.intent_digest,
        });
        Self::new(
            material,
            initial_binding,
            RetainedVersionOriginV1::Recovered,
            purpose,
            RetainedVersionHostStateV1 {
                dataset,
                initial_trainer: Some(trainer),
                trainer: None,
                initial_evaluator: evidence.into_evaluator(),
                evaluator: None,
                shared_evaluated: None,
                cut: None,
                expected: Some(RetainedVersionColdCutV1 {
                    training: original.training,
                    attestations: original.attestations,
                }),
                control: original.current,
                artifacts,
                phase: Some(phase),
                selection_reader: None,
                final_use_issuer: None,
            },
            lifetime,
        )
    }

    fn new(
        material: OriginalCellQ24MaterialReceiptConfigV1,
        initial_binding: Digest32,
        origin: RetainedVersionOriginV1,
        purpose: RetainedVersionPurposeV1,
        state: RetainedVersionHostStateV1,
        lifetime: Duration,
    ) -> Result<Self, Error> {
        if lifetime.is_zero() || lifetime > Duration::from_secs(300) {
            return Err(Error::Binding("original Version lifetime"));
        }
        let end = Instant::now().checked_add(lifetime).ok_or(Error::Clock)?;
        Ok(Self {
            material,
            initial_binding,
            origin,
            purpose,
            state: Mutex::new(state),
            preparation_requested: AtomicBool::new(origin == RetainedVersionOriginV1::Recovered),
            publication_requested: AtomicBool::new(origin == RetainedVersionOriginV1::Recovered),
            issuer_worker_started: AtomicBool::new(origin == RetainedVersionOriginV1::Recovered),
            final_use_outcome: AtomicU8::new(match origin {
                RetainedVersionOriginV1::Fresh => RetainedVersionFinalUseOutcomeV1::Awaiting as u8,
                RetainedVersionOriginV1::Recovered => {
                    RetainedVersionFinalUseOutcomeV1::Published as u8
                }
            }),
            runtime_started: AtomicBool::new(origin == RetainedVersionOriginV1::Recovered),
            end,
            runtime: Handle::try_current().map_err(|_| Error::Unavailable)?,
            connections: Arc::new(Semaphore::new(4)),
            installed: Notify::new(),
            prepared: Notify::new(),
        })
    }

    fn require_lifetime(&self) -> Result<(), Error> {
        if Instant::now() >= self.end {
            return Err(Error::Unavailable);
        }
        Ok(())
    }

    fn original_final_use_outcome(&self) -> RetainedVersionFinalUseOutcomeV1 {
        match self.final_use_outcome.load(Ordering::Acquire) {
            0 => RetainedVersionFinalUseOutcomeV1::Awaiting,
            1 => RetainedVersionFinalUseOutcomeV1::Requested,
            2 => RetainedVersionFinalUseOutcomeV1::Denied,
            4 => RetainedVersionFinalUseOutcomeV1::Published,
            _ => RetainedVersionFinalUseOutcomeV1::Uncertain,
        }
    }
}

//! A local, sealed view of the original published Version's same T/E channels.
//! It has no new-work method, owner factory, descriptor or reconnect interface.

use std::sync::Arc;

use super::OriginalCircuitRetainedVersionHostV1;
use super::RetainedVersionFinalUseOutcomeV1;
use super::RetainedVersionHostPhaseV1;
use super::super::Error;
use super::super::RetainedVersionOriginV1;
use super::super::RetainedVersionPurposeV1;
use crate::OriginalCellEvaluationCommandClientV1;
use crate::OriginalCellQ24TrainingCommandClientV1;
use crate::OriginalCircuitEvaluatedRetentionContextV1;
use crate::OriginalCircuitRetainedPublicationErrorV1;

pub struct OriginalCircuitPublishedEvidenceReadbackV1 {
    trainer: Arc<OriginalCellQ24TrainingCommandClientV1>,
    evaluator: Arc<OriginalCellEvaluationCommandClientV1>,
    context: OriginalCircuitEvaluatedRetentionContextV1,
}

impl Clone for OriginalCircuitPublishedEvidenceReadbackV1 {
    fn clone(&self) -> Self {
        Self {
            trainer: Arc::clone(&self.trainer),
            evaluator: Arc::clone(&self.evaluator),
            context: self.context.clone_for_original_receipt(),
        }
    }
}

impl OriginalCircuitPublishedEvidenceReadbackV1 {
    /// Perform actual original T/E reads. This is not a cached publication
    /// result or a new-work capability. Competing reads retain the original
    /// Unavailable/Unknown semantics; sharing creates no queue or retry.
    pub async fn read_original_predecessors(&self) -> Result<(), Error> {
        self.context
            .require_original_receipt_owners(self.trainer.as_ref(), self.evaluator.as_ref())
            .await?;
        Ok(())
    }

    pub(crate) fn require_original_context(
        &self,
        expected: &OriginalCircuitEvaluatedRetentionContextV1,
    ) -> Result<(), OriginalCircuitRetainedPublicationErrorV1> {
        if self.context.snapshot() != expected.snapshot()
            || self.context.receipt_context_binding() != expected.receipt_context_binding()
        {
            return Err(OriginalCircuitRetainedPublicationErrorV1::Binding(
                "same original published T/E context",
            ));
        }
        let at = super::super::super::now()?;
        self.context.original_receipt_predecessors(at)?;
        expected.original_receipt_predecessors(at)?;
        Ok(())
    }

    pub(crate) fn original_clients(
        &self,
    ) -> (&OriginalCellQ24TrainingCommandClientV1, &OriginalCellEvaluationCommandClientV1) {
        (self.trainer.as_ref(), self.evaluator.as_ref())
    }
}

impl OriginalCircuitRetainedVersionHostV1 {
    /// Consume the already retained clients only after actual Published and a
    /// full current read. A cold Published enum alone does not admit a reader.
    /// All aliases keep the original clients' one channel slot and lifetime.
    pub async fn share_original_evaluated_readbacks(
        self: Arc<Self>,
    ) -> Result<OriginalCircuitPublishedEvidenceReadbackV1, Error> {
        tokio::task::spawn_blocking(move || {
            self.require_lifetime()?;
            if self.purpose != RetainedVersionPurposeV1::EvaluatedNoUpdate
                || self.original_final_use_outcome() != RetainedVersionFinalUseOutcomeV1::Published
            {
                return Err(Error::ReadbackRequired);
            }
            let mut state = self.state.try_lock().map_err(|_| Error::Busy)?;
            if let Err(error) = self.bind_original_predecessor(&mut state) {
                if self.origin == RetainedVersionOriginV1::Recovered {
                    state.selection_reader = None;
                }
                return Err(error);
            }
            let observed = if self.origin == RetainedVersionOriginV1::Recovered {
                self.read_original_recovery(&mut state)?
            } else {
                self.read_original(&state)?
            };
            if observed.publication().is_none()
                || state.selection_reader.is_none()
                || !matches!(
                    state.phase.as_ref(),
                    Some(RetainedVersionHostPhaseV1::Installed { .. } | RetainedVersionHostPhaseV1::Recovered(_))
                )
                || self.original_final_use_outcome() != RetainedVersionFinalUseOutcomeV1::Published
            {
                return Err(Error::ReadbackRequired);
            }
            let context = state.cut.as_ref().and_then(|cut| cut.evaluated.as_ref())
                .ok_or(Error::ReadbackRequired)?.clone_for_original_receipt();
            if state.shared_evaluated.is_none() {
                let original = match (state.trainer.take(), state.evaluator.take()) {
                    (Some(trainer), Some(evaluator)) => (trainer, evaluator),
                    _ => {
                        state.selection_reader = None;
                        return Err(Error::Unavailable);
                    }
                };
                let (trainer, evaluator) = match context.seal_original_readback_owners(original.0, original.1) {
                    Ok(value) => value,
                    Err(error) => {
                        state.selection_reader = None;
                        return Err(error.into());
                    }
                };
                state.shared_evaluated = Some(OriginalCircuitPublishedEvidenceReadbackV1 {
                    trainer,
                    evaluator,
                    context: context.clone_for_original_receipt(),
                });
            }
            let shared = state.shared_evaluated.as_ref().ok_or(Error::Unavailable)?;
            shared.require_original_context(&context)?;
            self.require_lifetime()?;
            Ok(shared.clone())
        }).await.map_err(|_| Error::CommitUncertain)?
    }
}

//! Actual Dataset/Trainer and original publication observations in one host.
//! Full signatures are pinned; no observed result substitutes for a later read.
use codex_hepta_learning_artifacts::LearningIterationCoordinatorV1;

use super::super::super::context::PublicationAccess;
use super::super::Error;
use super::super::OriginalCircuitRetainedVersionReadbackV1;
use super::super::RetainedVersionOriginV1;
use super::super::RetainedVersionPurposeV1;
use super::super::context::OriginalVersionCut;
use super::OriginalCircuitRetainedVersionHostV1;
use super::RetainedVersionHostPhaseV1;
use super::RetainedVersionHostStateV1;
use super::artifact;
use crate::NeuronGenerationCurrentOwnerV1;
use crate::NeuronGenerationUpdateReadbackV1;
use crate::OriginalCellEvaluationCommandClientV1;
use crate::OriginalCellEvaluationCommandConnectionV1;
use crate::OriginalCellQ24DatasetCommandReadbackV1;
use crate::OriginalCellQ24TrainingCommandClientV1;
use crate::OriginalCellQ24TrainingCommandConnectionV1;

impl OriginalCircuitRetainedVersionHostV1 {
    pub(super) fn bind_original_predecessor(
        &self,
        state: &mut RetainedVersionHostStateV1,
    ) -> Result<(), Error> {
        self.require_lifetime()?;
        if state.cut.is_some() {
            return state.require_cut_current(&self.runtime);
        }
        let dataset = self
            .runtime
            .block_on(OriginalCellQ24DatasetCommandReadbackV1::readback(
                &state.dataset,
            ))?;
        OriginalCellQ24DatasetCommandReadbackV1::verify_original_cut(&state.dataset, &dataset)?;
        let original = state
            .initial_trainer
            .take()
            .ok_or(Error::ReadbackRequired)?;
        let trainer = OriginalCellQ24TrainingCommandConnectionV1::bind_original_dataset(
            original,
            dataset.clone(),
        )?;
        let training = self
            .runtime
            .block_on(OriginalCellQ24TrainingCommandClientV1::readback(&trainer))?;
        let (cut, evaluator) = match self.purpose {
            RetainedVersionPurposeV1::TrainingNoUpdate => (
                OriginalVersionCut::from_original(
                    self.material.clone(),
                    dataset,
                    &training,
                    self.origin,
                )?,
                None,
            ),
            RetainedVersionPurposeV1::EvaluatedNoUpdate => {
                let initial = state
                    .initial_evaluator
                    .take()
                    .ok_or(Error::ReadbackRequired)?;
                let evaluator = OriginalCellEvaluationCommandConnectionV1::bind_original_training(
                    initial,
                    dataset.snapshot().clone(),
                    &training,
                )?;
                let evaluation = self
                    .runtime
                    .block_on(OriginalCellEvaluationCommandClientV1::readback(&evaluator))?;
                let cut = OriginalVersionCut::from_original_evaluated(
                    self.material.clone(),
                    dataset,
                    &training,
                    &evaluation,
                    self.origin,
                )?;
                (cut, Some(evaluator))
            }
        };
        if let Some(expected) = &state.expected {
            let mut signatures = cut.dataset.attestations().to_vec();
            signatures.push(cut.training.training_evidence.clone());
            if let Some(context) = &cut.evaluated {
                signatures.push(context.evaluation_attestation().clone());
            }
            if expected.training != cut.training.training || expected.attestations != signatures {
                return Err(Error::Binding(
                    "same original complete cold E/D/T checkpoint",
                ));
            }
        }
        cut.require_fresh(super::super::now()?, PublicationAccess::Readback)?;
        state.trainer = Some(trainer);
        state.evaluator = evaluator;
        state.cut = Some(cut);
        Ok(())
    }

    /// A recovered publication is not a ready reader until the actual original
    /// predecessors, Artifact/CURRENT and held C owners agree across its read.
    /// A failed predecessor/publication read removes admission for new
    /// connections. Existing read-only connections keep their own checks.
    pub(super) fn read_original_recovery(
        &self,
        state: &mut RetainedVersionHostStateV1,
    ) -> Result<OriginalCircuitRetainedVersionReadbackV1, Error> {
        if self.origin != RetainedVersionOriginV1::Recovered {
            return self.read_original(state);
        }
        let retained_reader = state.selection_reader.take();
        let before = self.read_original(state)?;
        let reader = match retained_reader {
            Some(reader) => reader,
            None => state
                .build_original_selection_reader()?
                .ok_or(Error::ReadbackRequired)?,
        };
        let after = self.read_original(state)?;
        if before != after || after.publication().is_none() {
            return Err(Error::CommitUncertain);
        }
        state
            .cut
            .as_ref()
            .ok_or(Error::Unavailable)?
            .require_fresh(super::super::now()?, PublicationAccess::Readback)?;
        self.require_lifetime()?;
        state.selection_reader = Some(reader);
        self.installed.notify_waiters();
        Ok(after)
    }

    pub(super) fn read_original(
        &self,
        state: &RetainedVersionHostStateV1,
    ) -> Result<OriginalCircuitRetainedVersionReadbackV1, Error> {
        let started = super::super::now()?;
        self.require_lifetime()?;
        state.require_cut_current(&self.runtime)?;
        let before = state.artifacts.read_current()?;
        let first = state.observe_phase()?;
        // The second original peer reads cannot turn the first physical
        // publication read into a current one. Re-read the actual owner last.
        state.require_cut_current(&self.runtime)?;
        let last = state.observe_phase()?;
        let after = state.artifacts.read_current()?;
        artifact::require_same(&before, &after)?;
        if first != last {
            return Err(Error::Binding("original retained version changed"));
        }
        self.require_lifetime()?;
        state
            .cut
            .as_ref()
            .ok_or(Error::Unavailable)?
            .require_fresh(started, PublicationAccess::Readback)?;
        Ok(last)
    }
}

impl RetainedVersionHostStateV1 {
    pub(super) fn install_original_selection_reader(&mut self) -> Result<(), Error> {
        if self.selection_reader.is_some() {
            return Ok(());
        }
        self.selection_reader = self.build_original_selection_reader()?;
        Ok(())
    }

    fn build_original_selection_reader(
        &self,
    ) -> Result<
        Option<
            std::sync::Arc<
                crate::OriginalCircuitLearningReadOwnerV1<
                    codex_hepta_neuron::FileAnchorWitnessStore,
                    codex_hepta_neuron::FileAnchorWitnessStore,
                >,
            >,
        >,
        Error,
    > {
        let original = match self.phase.as_ref() {
            Some(
                RetainedVersionHostPhaseV1::Installed { original, .. }
                | RetainedVersionHostPhaseV1::Recovered(original),
            ) => original,
            _ => return Ok(None),
        };
        let cut = self.cut.as_ref().ok_or(Error::Unavailable)?;
        let reader = match &cut.evaluated {
            None => {
                let context = crate::OriginalCircuitLearningReadContextV1 {
                    prefix: cut.training.training.clone(),
                    scope: cut.training.scope.clone(),
                    verifier: cut.training.verifier.clone(),
                    training_evidence: cut.training.training_evidence.clone(),
                    selection_evidence: None,
                };
                crate::OriginalCircuitLearningReadOwnerV1::from_original_owners(
                    original.cell.clone(),
                    original.source.as_ref().clone(),
                    original.identity.clone(),
                    context,
                )
            }
            Some(evaluated) => {
                let context =
                    crate::OriginalCircuitEvaluatedLearningReadContextV1::for_original_selection(
                        evaluated.clone_for_original_receipt(),
                    )
                    .map_err(|error| {
                        Error::Owner(crate::AgentdError::Invalid(error.to_string()))
                    })?;
                crate::OriginalCircuitLearningReadOwnerV1::from_original_evaluated_owners(
                    original.cell.clone(),
                    original.source.as_ref().clone(),
                    original.identity.clone(),
                    context,
                )
            }
        }
        .map_err(|error| Error::Owner(crate::AgentdError::Invalid(error.to_string())))?;
        Ok(Some(std::sync::Arc::new(reader)))
    }

    fn original_trainer(&self) -> Result<&OriginalCellQ24TrainingCommandClientV1, Error> {
        match self.phase.as_ref().ok_or(Error::CommitUncertain)? {
            RetainedVersionHostPhaseV1::Prepared { original, .. } => Ok(original.trainer()),
            _ => self.trainer.as_ref().or_else(|| {
                self.shared_evaluated.as_ref().map(|shared| shared.original_clients().0)
            }).ok_or(Error::Unavailable),
        }
    }

    fn original_evaluator(&self) -> Result<&OriginalCellEvaluationCommandClientV1, Error> {
        match self.phase.as_ref().ok_or(Error::CommitUncertain)? {
            RetainedVersionHostPhaseV1::Prepared { original, .. } => {
                original.evaluator().ok_or(Error::Unavailable)
            }
            _ => self.evaluator.as_ref().or_else(|| {
                self.shared_evaluated.as_ref().map(|shared| shared.original_clients().1)
            }).ok_or(Error::Unavailable),
        }
    }

    pub(super) fn require_cut_current(
        &self,
        runtime: &tokio::runtime::Handle,
    ) -> Result<(), Error> {
        let started = super::super::now()?;
        let cut = self.cut.as_ref().ok_or(Error::Unavailable)?;
        let actual = runtime.block_on(OriginalCellQ24DatasetCommandReadbackV1::readback(
            &self.dataset,
        ))?;
        OriginalCellQ24DatasetCommandReadbackV1::verify_original_cut(&self.dataset, &actual)?;
        if actual != cut.dataset {
            return Err(Error::Binding(
                "same actual original E/D receipt and signatures",
            ));
        }
        match &cut.evaluated {
            None => {
                runtime.block_on(cut.training.require_training_current(
                    self.original_trainer()?,
                    PublicationAccess::Readback,
                ))?
            }
            Some(context) => runtime.block_on(context.require_current(
                self.original_trainer()?,
                self.original_evaluator()?,
                PublicationAccess::Readback,
            ))?,
        }
        cut.require_fresh(started, PublicationAccess::Readback)
    }

    fn observe_phase(&self) -> Result<OriginalCircuitRetainedVersionReadbackV1, Error> {
        let cut = self.cut.as_ref().ok_or(Error::Unavailable)?;
        match self.phase.as_ref().ok_or(Error::CommitUncertain)? {
            RetainedVersionHostPhaseV1::Awaiting { .. } => Err(Error::ReadbackRequired),
            RetainedVersionHostPhaseV1::Prepared { original, .. } => {
                let coordinator =
                    LearningIterationCoordinatorV1::from_snapshot(cut.training.training.clone())?;
                let operation = crate::learning_retained_task_operation_id_v1(&coordinator)?;
                let intent = original.intent_digest();
                let prepared = NeuronGenerationCurrentOwnerV1::recover_operation(
                    &self.control,
                    operation.as_str(),
                    intent,
                )?;
                if !matches!(
                    NeuronGenerationCurrentOwnerV1::read_operation(&self.control, &prepared,)?,
                    NeuronGenerationUpdateReadbackV1::Prepared
                ) {
                    // A published Control record is not an already held C
                    // Source/Cell owner, and never causes factory replay.
                    return Err(Error::CommitUncertain);
                }
                Ok(OriginalCircuitRetainedVersionReadbackV1 {
                    intent,
                    publication: None,
                })
            }
            RetainedVersionHostPhaseV1::Installed { original, .. }
            | RetainedVersionHostPhaseV1::Recovered(original) => original.observe(cut),
        }
    }
}

